/// Sets the element at index `i` of the vector `a` to `val`.
/// Panics if `i` is out of bounds.
pub fn set_at(a: &mut Vec<i32>, i: usize, val: i32) {
    a[i] = val;
}

/// Overwrites every element of `a` (whose length is assumed to be `N`)
/// with `N + 1`. The auxiliary vector `sum` is assumed to have length 1
/// and its length is not changed (and we do not modify its contents).
/// It is assumed `N > 0 && N < 1000`.
pub fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // We don't need to change `sum`, but bind it to `_` to avoid unused-parameter warnings.
    let _ = sum;
    
    let new_val = N + 1;
    let len = N as usize; // safe because 0 < N < 1000
    
    for idx in 0..len {
        set_at(a, idx, new_val);
    }
}

